require("src/utils/List")
local htmlparser = require("src/utils/html/htmlparser")
local JQRichTextUtils = require("src/ui/components/reach/richtext/JQRichTextUtils")
local JQRichTextConstants = require("src/ui/components/reach/richtext/JQRichTextConstants")
local JQRichTextHtmlParser = class("JQRichTextHtmlParser")

function JQRichTextHtmlParser:ctor(format)
    self:initData(format)
end

function JQRichTextHtmlParser:initData(format)
    self.defaultFormat = format
    self.groupIndex = 1
    self.groupAlign = JQRichTextConstants.ALIGNMENT_LEFT
    self.formats = List()
end

function JQRichTextHtmlParser:parse(text)
    local tree = htmlparser.parse(text)
    table.foreach(tree.nodes, function(_, node)
        self:parseElement(node, self.defaultFormat:clone())
    end)
    self:decodeText()
    self:splitWithLF()
    self:checkNullString()
    return self.formats
end

function JQRichTextHtmlParser:parseElement(element, format)
    if element.name == JQRichTextConstants.HTML.TAG_DIV then
        self:parseAttributes(element.attributes, format)
        table.foreach(element.nodes, function(_, node)
            self:parseElement(node, format:clone())
        end)
    elseif element.name == JQRichTextConstants.HTML.TAG_TEXT then
        self:parseAttributes(element.attributes, format)
        table.foreach(element.nodes, function(_, node)
            self:parseElement(node, format)
        end)
        format:setType(JQRichTextConstants.TYPES.TEXT)
        if not format.isTextSetup then
            format:setText(element:getcontent())
        end
        table.insert(self.formats, format)
    elseif element.name == JQRichTextConstants.HTML.TAG_BOLD then
        format:setBold(true)
        table.foreach(element.nodes, function(_, node)
            self:parseElement(node, format)
        end)

        if not format.isReviseInsert then
            format:setText(element:getcontent())
        end
    elseif element.name == JQRichTextConstants.HTML.TAG_OPTS then
        self:parseParameters(element.attributes, format)
        format:setText(element:getcontent())
    end
end

function JQRichTextHtmlParser:startAlign(attributes)
    local align = checkint(attributes[JQRichTextConstants.HTML.ATTRIBUTE_ALIGN])
    self.groupIndex = JQRichTextUtils:newGroupIndex()
    self.groupAlign = align or JQRichTextConstants.ALIGNMENT_LEFT
end

function JQRichTextHtmlParser:endAlign()
    self.groupIndex = JQRichTextUtils:newGroupIndex()
    self.groupAlign = JQRichTextConstants.ALIGNMENT_LEFT
end

function JQRichTextHtmlParser:parseAttributes(attributes, format)
    for name, value in pairs(attributes) do
        if name == JQRichTextConstants.HTML.ATTRIBUTE_COLOR then
            format:setColor(JQRichTextUtils:toColor(value))
        elseif name == JQRichTextConstants.HTML.ATTRIBUTE_FONT_SIZE then
            format:setFontSize(tonumber(value))
        elseif name == JQRichTextConstants.HTML.ATTRIBUTE_FONT_NAME then
            format:setFontName(value)
        elseif name == JQRichTextConstants.HTML.ATTRIBUTE_RES then
            format:setResPath(value)
        elseif name == JQRichTextConstants.HTML.ATTRIBUTE_IMG_SIZE then
            format:setImgSize(self:toSize(value))
        elseif name == JQRichTextConstants.HTML.ATTRIBUTE_BG_COLOR then
            format:setBgColor(JQRichTextUtils:toColor(value))
        elseif name == JQRichTextConstants.HTML.ATTRIBUTE_ALIGN then
            format:setGroup(JQRichTextUtils:newGroupIndex(), self:toAlign(value))
        elseif name == JQRichTextConstants.HTML.ATTRIBUTE_UNDERLINE then
            format:setUnderlineWidth(tonumber(value))
        elseif name == JQRichTextConstants.HTML.ATTRIBUTE_LINE_HEIGHT then
            format:setLineHeight(tonumber(value))
        end
    end
end

function JQRichTextHtmlParser:parseParameters(attributes, format)
    for name, value in pairs(attributes) do
        if name == JQRichTextConstants.HTML.OPTS_INSET then
            format:setIsReviseInsert(tonumber(value) > 0)
        end
    end
end

function JQRichTextHtmlParser:decodeText()
    table.foreach(self.formats, function(_, format)
        if format.type == JQRichTextConstants.TYPES.TEXT then
            format:setText(string.restorehtmlspecialchars(format.text))
        end
    end)
end

function JQRichTextHtmlParser:splitWithLF()
    local index = 1
    while (index <= #self.formats) do
        local format = self.formats[index]
        if format.type == JQRichTextConstants.TYPES.TEXT then
            table.remove(self.formats, index)
            local newFormats = self:splitFormatWithLF(format)
            while (#newFormats > 0) do
                table.insert(self.formats, index, table.remove(newFormats, 1))
                index = index + 1
            end
        else
            index = index + 1
        end
    end
end

function JQRichTextHtmlParser:splitFormatWithLF(format)
    local text = format.text
    local startIndex = 0
    local newFormats = {}
    while (true) do
        local beganIndex, endedIndex = string.find(text, "\n", startIndex)
        if beganIndex then
            local newFormat = format:clone()
            newFormat:setText(string.sub(text, startIndex, beganIndex - 1))
            newFormat:setTailWithLF(true)
            table.insert(newFormats, newFormat)
            startIndex = endedIndex + 1
        else
            if startIndex <= #text then
                local newFormat = format:clone()
                newFormat:setText(string.sub(text, startIndex))
                newFormat:setTailWithLF(false)
                table.insert(newFormats, newFormat)
            end
            break
        end
    end
    return newFormats
end

function JQRichTextHtmlParser:checkNullString()
    local index = 1
    while (index <= #self.formats) do
        local format = self.formats[index]
        if format.type == JQRichTextConstants.TYPES.TEXT then
            if format.text == "" and not format.tailWithLF then
                format:setNullString(true)
            else
                format:setNullString(false)
            end
        end
        index = index + 1
    end
end

function JQRichTextHtmlParser:toSize(size)
    local w, h = unpack(string.split(size, ","))
    return {
        width = tonumber(w),
        height = tonumber(h)
    }
end

function JQRichTextHtmlParser:toAlign(align)
    align = checkint(align)
    if align == JQRichTextConstants.ALIGNMENT_LEFT or align == JQRichTextConstants.ALIGNMENT_CENTER or align ==
        JQRichTextConstants.ALIGNMENT_RIGHT then
        return align
    else
        return JQRichTextConstants.ALIGNMENT_LEFT
    end
end

return JQRichTextHtmlParser
